class Solution {
    public List<Integer> addToArrayForm(int[] num,int k){
        List<Integer> digits=new ArrayList<>();
        for(int i=num.length-1;i>=0||k>0;i--){
            if(i>=0)k+=num[i];
            digits.add(k%10);
            k/=10;
        }
        Collections.reverse(digits);
        return digits;
    }
}

code.kotlin:
class Solution {
    fun addToArrayForm(num:IntArray,kInput:Int):List<Int>{
        var k=kInput;
        val digits=mutableListOf<Int>();
        var i=num.lastIndex;
        while(i>=0||k>0){
            if(i>=0)k+=num[i--];
            digits.add(k%10);
            k/=10
        };
        digits.reverse();
        return digits
    }
}

code.cpp:
class Solution {
    public: vector<int> addToArrayForm(vector<int>& num,int k){
        vector<int> digits;
        for(int i=num.size()-1;i>=0||k>0;--i){
            if(i>=0)k+=num[i];
            digits.push_back(k%10);
            k/=10;
        }
        reverse(digits.begin(),digits.end());
        return digits;
    }
};
